#include <cmath>
#include <vector>
#include <iostream>

struct Vec2 { float x, y; };

struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    float mass;
    float restitution;  // bounciness (0-1)
    float radius;       // for circle collision
    bool isStatic;      // immovable object

    RigidBody(float x, float y, float mass, float rest, float r)
        : position{x, y}, velocity{0, 0}, mass(mass), restitution(rest), radius(r), isStatic(false) {}
};

class PhysicsWorld {
    std::vector<RigidBody*> bodies;
    Vec2 gravity = {0, 981};  // pixels/s^2 downward

public:
    void addBody(RigidBody* body) { bodies.push_back(body); }

    void update(float dt) {
        // Apply forces and integrate
        for (auto* body : bodies) {
            if (body->isStatic) continue;

            // Apply gravity
            body->velocity.y += gravity.y * dt;

            // Update position (Euler integration)
            body->position.x += body->velocity.x * dt;
            body->position.y += body->velocity.y * dt;
        }

        // Detect and resolve collisions
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                resolveCollision(bodies[i], bodies[j]);
            }
        }

        // Ground plane
        for (auto* body : bodies) {
            if (body->isStatic) continue;
            if (body->position.y + body->radius > 600) {
                body->position.y = 600 - body->radius;
                body->velocity.y = -body->velocity.y * body->restitution;
            }
        }
    }

    bool circleCollision(const RigidBody* a, const RigidBody* b, float& overlap, Vec2& normal) {
        float dx = b->position.x - a->position.x;
        float dy = b->position.y - a->position.y;
        float dist = std::sqrt(dx*dx + dy*dy);
        float minDist = a->radius + b->radius;

        if (dist < minDist && dist > 0.0001f) {
            overlap = minDist - dist;
            normal = {dx/dist, dy/dist};
            return true;
        }
        return false;
    }

    void resolveCollision(RigidBody* a, RigidBody* b) {
        if (a->isStatic && b->isStatic) return;

        float overlap;
        Vec2 normal;
        if (!circleCollision(a, b, overlap, normal)) return;

        // Separate objects
        if (!a->isStatic) {
            a->position.x -= normal.x * overlap * 0.5f;
            a->position.y -= normal.y * overlap * 0.5f;
        }
        if (!b->isStatic) {
            b->position.x += normal.x * overlap * 0.5f;
            b->position.y += normal.y * overlap * 0.5f;
        }

        // Calculate relative velocity
        float relVx = a->velocity.x - b->velocity.x;
        float relVy = a->velocity.y - b->velocity.y;
        float relVelAlongNormal = relVx * normal.x + relVy * normal.y;

        if (relVelAlongNormal > 0) return;  // Moving apart

        // Calculate impulse (simplified - assumes equal mass inertia)
        float j = -(1 + a->restitution * b->restitution) * relVelAlongNormal;
        j /= (a->isStatic ? 0 : 1/a->mass) + (b->isStatic ? 0 : 1/b->mass);

        if (!a->isStatic) {
            a->velocity.x += j * normal.x / a->mass;
            a->velocity.y += j * normal.y / a->mass;
        }
        if (!b->isStatic) {
            b->velocity.x -= j * normal.x / b->mass;
            b->velocity.y -= j * normal.y / b->mass;
        }
    }
};

int main() {
    PhysicsWorld world;

    RigidBody ball(200, 0, 1, 0.8f, 20);
    RigidBody ball2(230, 0, 2, 0.5f, 25);
    RigidBody floor(0, 0, 9999, 0, 0);
    floor.isStatic = true;

    world.addBody(&ball);
    world.addBody(&ball2);

    for (int frame = 0; frame < 60; ++frame) {
        world.update(1.0f/60.0f);
        std::cout << "Ball: (" << ball.position.x << ", " << ball.position.y << ") "
                  << "Ball2: (" << ball2.position.x << ", " << ball2.position.y << ")\n";
    }
    return 0;
}

#include <iostream>
#include <memory>
#include <vector>
#include <functional>

// Node status
enum class Status { SUCCESS, FAILURE, RUNNING };

// Forward declarations
class BTNode;
class BehaviorTree;

// Base class for all nodes
class BTNode {
public:
    virtual ~BTNode() = default;
    virtual Status execute(Blackboard& bb, float dt) = 0;
    virtual std::string getName() const = 0;
};

// Blackboard: shared memory for the AI
class Blackboard {
    std::unordered_map<std::string, std::any> data;
public:
    template<typename T>
    void set(const std::string& key, const T& value) { data[key] = value; }

    template<typename T>
    T get(const std::string& key, const T& defaultValue = T()) const {
        auto it = data.find(key);
        if (it != data.end()) {
            try { return std::any_cast<T>(it->second); }
            catch(...) {}
        }
        return defaultValue;
    }

    bool has(const std::string& key) const { return data.count(key) > 0; }
};

// Condition node: checks if something is true
class ConditionNode : public BTNode {
    std::function<bool(Blackboard&)> condition;
    std::string name;
public:
    ConditionNode(const std::string& name, std::function<bool(Blackboard&)> cond)
        : name(name), condition(cond) {}

    Status execute(Blackboard& bb, float dt) override {
        return condition(bb) ? Status::SUCCESS : Status::FAILURE;
    }
    std::string getName() const override { return name; }
};

// Action node: performs an action
class ActionNode : public BTNode {
    std::function<Status(Blackboard&, float)> action;
    std::string name;
public:
    ActionNode(const std::string& name, std::function<Status(Blackboard&, float)> act)
        : name(name), action(act) {}

    Status execute(Blackboard& bb, float dt) override {
        return action(bb, dt);
    }
    std::string getName() const override { return name; }
};

// Composite nodes
class CompositeNode : public BTNode {
protected:
    std::vector<std::unique_ptr<BTNode>> children;
public:
    void addChild(std::unique_ptr<BTNode> child) {
        children.push_back(std::move(child));
    }
};

// Sequence: runs all children until one fails
class SequenceNode : public CompositeNode {
public:
    Status execute(Blackboard& bb, float dt) override {
        for (auto& child : children) {
            Status status = child->execute(bb, dt);
            if (status != Status::SUCCESS) {
                return status;
            }
        }
        return Status::SUCCESS;
    }
    std::string getName() const override { return "Sequence"; }
};

// Selector: runs children until one succeeds
class SelectorNode : public CompositeNode {
public:
    Status execute(Blackboard& bb, float dt) override {
        for (auto& child : children) {
            Status status = child->execute(bb, dt);
            if (status != Status::FAILURE) {
                return status;
            }
        }
        return Status::FAILURE;
    }
    std::string getName() const override { return "Selector"; }
};

// Decorator: inverts child result
class InvertDecorator : public BTNode {
    std::unique_ptr<BTNode> child;
public:
    InvertDecorator(std::unique_ptr<BTNode> child) : child(std::move(child)) {}

    Status execute(Blackboard& bb, float dt) override {
        Status s = child->execute(bb, dt);
        if (s == Status::SUCCESS) return Status::FAILURE;
        if (s == Status::FAILURE) return Status::SUCCESS;
        return Status::RUNNING;
    }
    std::string getName() const override { return "Invert"; }
};

// The Behavior Tree itself
class BehaviorTree {
    std::unique_ptr<BTNode> root;
    Blackboard blackboard;
public:
    void setRoot(std::unique_ptr<BTNode> node) { root = std::move(node); }
    Blackboard& getBlackboard() { return blackboard; }

    Status update(float dt) {
        if (!root) return Status::FAILURE;
        return root->execute(blackboard, dt);
    }
};

// Example: Build a simple enemy AI tree
int main() {
    BehaviorTree tree;
    auto& bb = tree.getBlackboard();

    // Set initial blackboard values
    bb.set("health", 100.0f);
    bb.set("ammo", 30);
    bb.set("canSeePlayer", false);
    bb.set("playerDistance", 100.0f);

    // Build tree:
    // Selector
    //   Sequence (attack player)
    //     Condition: canSeePlayer
    //     Action: shoot
    //   Sequence (search)
    //     Action: patrol
    auto root = std::make_unique<SelectorNode>();

    // Attack branch
    auto attackSeq = std::make_unique<SequenceNode>();
    attackSeq->addChild(std::make_unique<ConditionNode>("CanSeePlayer", 
        [](Blackboard& b) { return b.get<bool>("canSeePlayer"); }
    ));
    attackSeq->addChild(std::make_unique<ConditionNode>("HasAmmo",
        [](Blackboard& b) { return b.get<int>("ammo") > 0; }
    ));
    attackSeq->addChild(std::make_unique<ActionNode>("Shoot",
        [](Blackboard& bb, float dt) -> Status {
            std::cout << "Enemy shoots!\n";
            int ammo = bb.get<int>("ammo");
            bb.set("ammo", ammo - 1);
            return Status::SUCCESS;
        }
    ));
    root->addChild(std::move(attackSeq));

    // Patrol branch
    auto patrolSeq = std::make_unique<SequenceNode>();
    patrolSeq->addChild(std::make_unique<ActionNode>("Patrol",
        [](Blackboard& bb, float dt) -> Status {
            std::cout << "Enemy patrols...\n";
            return Status::RUNNING;
        }
    ));
    root->addChild(std::move(patrolSeq));

    tree.setRoot(std::move(root));

    // Simulate
    for (int frame = 0; frame < 10; ++frame) {
        std::cout << "Frame " << frame << ": ";
        tree.update(1.0f/60.0f);
    }
    return 0;
}

#include <vector>
#include <queue>
#include <unordered_map>
#include <cmath>
#include <algorithm>
#include <iostream>

struct Vec2i { int x, y; };

struct Node {
    Vec2i pos;
    int g, h, f;
    Node* parent;

    Node(int x, int y) : pos{x, y}, g(0), h(0), f(0), parent(nullptr) {}
};

// Priority queue helper - returns node with lowest f-score
struct CompareNode {
    bool operator()(Node* a, Node* b) { return a->f > b->f; }
};

class Pathfinder {
    int width, height;
    std::vector<bool> obstacles;  // true = blocked

    // 4-directional neighbors (use 8 for diagonal movement)
    const Vec2i dirs[4] = {{0,1}, {0,-1}, {1,0}, {-1,0}};

public:
    Pathfinder(int w, int h) : width(w), height(h) {
        obstacles.resize(w * h, false);
    }

    void setObstacle(int x, int y, bool blocked) {
        obstacles[y * width + x] = blocked;
    }

    bool isBlocked(int x, int y) const {
        if (x < 0 || x >= width || y < 0 || y >= height) return true;
        return obstacles[y * width + x];
    }

    // Heuristic: Manhattan distance (good for 4-directional grids)
    int heuristic(int x1, int y1, int x2, int y2) const {
        return std::abs(x1 - x2) + std::abs(y1 - y2);
    }

    std::vector<Vec2i> findPath(int startX, int startY, int endX, int endY) {
        std::priority_queue<Node*, std::vector<Node*>, CompareNode> openSet;
        std::unordered_map<int, Node*> allNodes;
        std::vector<Node*> toDelete;

        auto getKey = [](int x, int y) { return y * 10000 + x; };

        // Start node
        Node* start = new Node(startX, startY);
        start->g = 0;
        start->h = heuristic(startX, startY, endX, endY);
        start->f = start->h;
        openSet.push(start);
        allNodes[getKey(startX, startY)] = start;
        toDelete.push_back(start);

        while (!openSet.empty()) {
            Node* current = openSet.top();
            openSet.pop();

            // Reached goal!
            if (current->pos.x == endX && current->pos.y == endY) {
                // Reconstruct path
                std::vector<Vec2i> path;
                Node* node = current;
                while (node) {
                    path.push_back(node->pos);
                    node = node->parent;
                }
                std::reverse(path.begin(), path.end());

                // Cleanup
                for (auto* n : toDelete) delete n;
                return path;
            }

            // Check neighbors
            for (auto& dir : dirs) {
                int nx = current->pos.x + dir.x;
                int ny = current->pos.y + dir.y;

                if (isBlocked(nx, ny)) continue;

                int key = getKey(nx, ny);
                Node* neighbor;

                if (allNodes.count(key)) {
                    neighbor = allNodes[key];
                } else {
                    neighbor = new Node(nx, ny);
                    allNodes[key] = neighbor;
                    toDelete.push_back(neighbor);
                }

                int tentativeG = current->g + 1;

                if (tentativeG < neighbor->g || neighbor->g == 0) {
                    neighbor->parent = current;
                    neighbor->g = tentativeG;
                    neighbor->h = heuristic(nx, ny, endX, endY);
                    neighbor->f = neighbor->g + neighbor->h;
                    openSet.push(neighbor);
                }
            }
        }

        // No path found
        for (auto* n : toDelete) delete n;
        return {};
    }
};

int main() {
    Pathfinder pf(10, 10);

    // Add some obstacles
    pf.setObstacle(3, 2, true);
    pf.setObstacle(3, 3, true);
    pf.setObstacle(3, 4, true);
    pf.setObstacle(3, 5, true);
    pf.setObstacle(5, 5, true);
    pf.setObstacle(5, 6, true);

    auto path = pf.findPath(0, 0, 9, 9);

    if (path.empty()) {
        std::cout << "No path found!\n";
    } else {
        std::cout << "Path found (" << path.size() << " steps):\n";
        for (auto& p : path) {
            std::cout << "  (" << p.x << ", " << p.y << ")\n";
        }

        // Visualize
        for (int y = 0; y < 10; ++y) {
            for (int x = 0; x < 10; ++x) {
                bool onPath = false;
                for (auto& p : path) {
                    if (p.x == x && p.y == y) { onPath = true; break; }
                }
                if (onPath) std::cout << "* ";
                else if (pf.isBlocked(x, y)) std::cout << "# ";
                else if (x == 0 && y == 0) std::cout << "S ";
                else if (x == 9 && y == 9) std::cout << "E ";
                else std::cout << ". ";
            }
            std::cout << "\n";
        }
    }
    return 0;
}

#include <vector>
#include <random>
#include <cmath>
#include <iostream>

class PerlinNoise {
    std::vector<int> p;

public:
    PerlinNoise(unsigned int seed = 42) {
        p.resize(512);
        std::vector<int> perm(256);
        std::iota(perm.begin(), perm.end(), 0);
        std::mt19937 rng(seed);
        std::shuffle(perm.begin(), perm.end(), rng);
        for (int i = 0; i < 256; ++i) p[i] = p[i+256] = perm[i];
    }

    double fade(double t) { return t*t*t*(t*(t*6-15)+10); }
    double lerp(double a, double b, double t) { return a + t*(b-a); }
    double grad(int hash, double x, double y) {
        int h = hash & 3;
        double u = h<2 ? x : y;
        double v = h<2 ? y : x;
        return ((h&1)==0 ? u : -u) + ((h&2)==0 ? v : -v);
    }

    double noise(double x, double y) {
        int X = (int)std::floor(x) & 255;
        int Y = (int)std::floor(y) & 255;
        x -= std::floor(x);
        y -= std::floor(y);
        double u = fade(x);
        double v = fade(y);
        int aa = p[p[X]+Y];
        int ab = p[p[X]+Y+1];
        int ba = p[p[X+1]+Y];
        int bb = p[p[X+1]+Y+1];
        return lerp(
            lerp(grad(aa, x, y), grad(ba, x-1, y), u),
            lerp(grad(ab, x, y-1), grad(bb, x-1, y-1), u),
            v
        );
    }

    double octaveNoise(double x, double y, int octaves, double persistence = 0.5) {
        double total = 0;
        double frequency = 1;
        double amplitude = 1;
        double maxValue = 0;
        for (int i = 0; i < octaves; ++i) {
            total += noise(x * frequency, y * frequency) * amplitude;
            maxValue += amplitude;
            amplitude *= persistence;
            frequency *= 2;
        }
        return total / maxValue;
    }
};

// Generate a terrain heightmap
std::vector<std::vector<float>> generateTerrain(int width, int height, int seed) {
    PerlinNoise perlin(seed);
    std::vector<std::vector<float>> terrain(width, std::vector<float>(height));

    for (int x = 0; x < width; ++x) {
        for (int y = 0; y < height; ++y) {
            float nx = x / (float)width - 0.5f;
            float ny = y / (float)height - 0.5f;

            // Use 6 octaves of noise with 0.5 persistence
            float elevation = perlin.octaveNoise(nx * 4, ny * 4, 6, 0.5f);

            // Scale to [0, 1] from [-1, 1]
            elevation = (elevation + 1) / 2;
            terrain[x][y] = elevation;
        }
    }
    return terrain;
};

int main() {
    auto terrain = generateTerrain(32, 32, 12345);

    // Print as ASCII
    for (int y = 0; y < 32; ++y) {
        for (int x = 0; x < 32; ++x) {
            float h = terrain[x][y];
            char c;
            if (h < 0.2f) c = '~';  // deep water
            else if (h < 0.35f) c = '.';  // shallow water
            else if (h < 0.45f) c = ',';  // beach
            else if (h < 0.6f) c = '#';   // grass
            else if (h < 0.75f) c = '^';  // forest
            else if (h < 0.9f) c = 'A';   // mountain
            else c = '%';  // snow
            std::cout << c << ' ';
        }
        std::cout << '\n';
    }
    return 0;
}

#include <vector>
#include <cmath>
#include <random>
#include <iostream>

class NeuralNetwork {
    struct Layer {
        std::vector<std::vector<float>> weights;
        std::vector<float> biases;
        std::vector<float> outputs;

        Layer(int inputs, int outputs, std::mt19937& rng) {
            std::normal_distribution<float> dist(0, 1);
            weights.resize(outputs, std::vector<float>(inputs));
            biases.resize(outputs);
            this->outputs.resize(outputs);

            for (int o = 0; o < outputs; ++o) {
                for (int i = 0; i < inputs; ++i)
                    weights[o][i] = dist(rng) * sqrt(2.0f / inputs);
                biases[o] = dist(rng) * 0.1f;
            }
        }

        void forward(const std::vector<float>& input) {
            for (int o = 0; o < (int)outputs.size(); ++o) {
                float sum = biases[o];
                for (int i = 0; i < (int)input.size(); ++i)
                    sum += weights[o][i] * input[i];
                outputs[o] = std::max(0.0f, sum);  // ReLU activation
            }
        }
    };

    std::vector<Layer> layers;

public:
    NeuralNetwork(const std::vector<int>& topology) {
        std::random_device rd;
        std::mt19937 rng(rd());
        for (size_t i = 0; i < topology.size() - 1; ++i)
            layers.emplace_back(topology[i], topology[i+1], rng);
    }

    std::vector<float> predict(const std::vector<float>& input) {
        if (layers.empty()) return input;

        std::vector<float> current = input;
        for (auto& layer : layers) {
            layer.forward(current);
            current = layer.outputs;
        }
        return current;
    }
};

// Example: Train AI to play a simple game
int main() {
    // Network: 4 inputs -> 16 hidden -> 8 hidden -> 2 outputs (left, right)
    NeuralNetwork ai({4, 16, 8, 2});

    // Example game state: [ballX, ballY, paddleY, ballSpeedX]
    std::vector<float> gameState = {0.5f, 0.3f, 0.4f, -0.2f};

    auto action = ai.predict(gameState);
    std::cout << "Action values: left=" << action[0] << ", right=" << action[1] << "\n";
